"note": "인카운터 그림 (2026-10-03), 그림만 자름. 글: 그는 어둠속에서 기괴한 가면을 쓰고, 그의 머리엔 신성한 붉은 빛이 원을 그립니다. 당신에게 꼭 설명하고 싶을겁니다. 귀신과 당신, 그리고 신에 대하여",
"rank": "",
