"cat": "scene",
"sub": "인카운터",
"name": "기나긴 해변",
"src": "img/card/enc_long_beach.webp",
"note": "가로로 긴 해변을 달려 지나감. 말대가리는 심드렁, 무시. 분리: H-337 · 스프라이트 P-horsehead. 글: 그는 파도가 치는 해변에 누워있었습니다. 별로 관심이 없는 듯 합니다. 맵 계획: cave-3d/ENCOUNTER_MAPS.md",
