"note": "상인 인카운터. 스프라이트는 8 인물 → 게 요리사. 글: 그것은 게.. 이자 사람..이었습니다. 혹시 음식을 사고싶은지, 웃으며 물어봅니다. 요리의 냄새가 납니다. ...재료는 무엇이었을까요?",
"rank": "",
