"note": "맵 저 멀리 거대한 신이 앉아 있는 연출로 끝. 신은 11 가구 · 소품 → 인카운터 오브제 · NPC (H-340). 글: 별하늘이 빛나는 밤, 저 멀리 한 신이 앉아있습니다. 맙소사. 이곳이 정녕 감옥일까요?",
