"note": "소금의 왕 (500m 정도 크기) 인카운터. 글: 소금의 왕이 강림하였느니. 당신은 안쪽부터 부식됩니다. 당신의 알량한 의지와 함께.. 맵 계획: cave-3d/ENCOUNTER_MAPS.md",
