"src": "img/card/enc_dancers.webp",
"note": "3m쯤 되는 무희 3명이 춤추는 인카운터. 글: 거대한 무희들이 춤을 춥니다. 그들은 무아에 빠져있습니다. 향은 독할정도로 농염합니다. 맵 계획: cave-3d/ENCOUNTER_MAPS.md 무희는 한 명만 잘라 셋으로 복제 (11 가구 · 소품 → 인카운터 오브제 · NPC, H-348)",
